'use client';
import React from 'react';

import { SkinTonePickerLocation } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// A full-width, short panel: the grid recomputes columns from the
// available width, so a wide picker simply shows more per row.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  return (
    <div className="wa-stage">
      <div className="wa-chat">
        <div className="wa-bubble">Are we still on for the trip? 🏕️</div>
        <div className="wa-bubble wa-out">Yes! Bringing the tent and snacks</div>
      </div>
      <div className="wa-composer">
        <span aria-hidden>😊</span>
        <div className="wa-input">Type a message</div>
      </div>
      <RootComponent         className={className}
        searchPlaceholder="Search emoji"
        skinTonePickerLocation={SkinTonePickerLocation.NONE}
      >
        <Picker.Search />
        <Picker.Viewport>
          <Picker.List />
          <Picker.Empty />
        </Picker.Viewport>
        <Picker.CategoryNav />
      </RootComponent>
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.wa-stage {
  width: 680px;
  border-radius: 12px;
  overflow: hidden;
  background: #efeae2;
  font-family: 'Segoe UI', 'Helvetica Neue', Helvetica, Arial, sans-serif;
}
.wa-chat {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px 20px;
}
.wa-bubble {
  align-self: flex-start;
  max-width: 60%;
  padding: 6px 9px 8px;
  border-radius: 7.5px;
  background: #fff;
  color: #111b21;
  font-size: 14.2px;
  box-shadow: 0 1px 0.5px rgb(11 20 26 / 13%);
}
.wa-bubble.wa-out {
  align-self: flex-end;
  background: #d9fdd3;
}
.wa-composer {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  background: #f0f2f5;
}
.wa-input {
  flex: 1;
  padding: 9px 12px;
  border-radius: 8px;
  background: #fff;
  color: #3b4a54;
  font-size: 15px;
}

/* WhatsApp — emoji keyboard panel docked under a chat: wide and short,
   flat surfaces, green accent, tabs along the bottom like a keyboard. */
/* Picker styles — the source of truth for every stack variant. */
.wa-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #54656f;
  --epr-highlight-color: #00a884;
  --epr-hover-bg-color: #f5f6f6;
  --epr-focus-bg-color: #e9edef;
  --epr-search-input-bg-color: #f0f2f5;
  --epr-search-input-bg-color-active: #f0f2f5;
  --epr-search-border-color: transparent;
  --epr-search-border-color-active: transparent;
  --epr-search-input-height: 34px;
  --epr-search-input-border-radius: 8px;
  --epr-search-input-padding: 0 12px 0 36px;
  --epr-search-input-text-color: #111b21;
  --epr-search-input-placeholder-color: #667781;
  --epr-category-label-bg-color: #fffffff2;
  --epr-category-label-text-color: #667781;
  --epr-category-label-height: 28px;
  --epr-category-icon-active-color: #00a884;
  --epr-category-icon-inactive-color: #8696a0;
  --epr-category-navigation-button-size: 24px;
  --epr-emoji-size: 30px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 16px;
  width: 100%;
  height: 300px;
  border-top: 1px solid #e9edef;
  background: #fff;
}
.wa-picker [data-epr-part='search'] > * {
  padding: 10px 16px 4px;
}
.wa-picker [data-epr-part='category-label'] {
  font-size: 13px;
  font-weight: 500;
  text-transform: uppercase;
}
.wa-picker [data-epr-part='emoji'] {
  border-radius: 50%;
}
.wa-picker [data-epr-part='category-nav'] {
  border-top: 1px solid #e9edef;
}
.wa-picker [data-epr-part='category-nav'] > * {
  justify-content: space-between;
  padding: 6px 40px;
}
.wa-picker [data-epr-part='category-tab'][aria-selected='true']::after {
  content: '';
  position: absolute;
  right: -10px;
  bottom: -6px;
  left: -10px;
  height: 3px;
  border-radius: 3px 3px 0 0;
  background: #00a884;
}

